/// <summary>
/// METTelemetryDMFLogging class extending methods of METTelemetryBase class
/// </summary>
final class METTelemetryDMFLogging extends METTelemetryBase
{
    public DMFDefinitionGroupExecution dmfDefinitionGroupExecution;
    public notes error;

}

Method.Source:
/// <summary>
/// Constructor
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
/// <param name = "_error">_error</param>
protected void new( DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,  str _error)
{
    super();

    dmfDefinitionGroupExecution = _dmfDefinitionGroupExecution;
    this.error = _error;
    this.eventId = METApplicationInsightsEventIds::DMFLogging;
}

public static METTelemetryDMFLogging construct( DMFDefinitionGroupExecution _dmfDefinitionGroupExecution,  str _error)
{
    return new METTelemetryDMFLogging(_dmfDefinitionGroupExecution,_error);
}

/// <summary>
/// shouldLogEvent
/// </summary>
/// <returns>boolean</returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// populateProperties
/// </summary>
protected void populateProperties()
{
    // Setting elapsed milliseconds in the concrete implementation so that the implementer can decide what is the right way to get elapsed time.
    this.setElapsedMilliseconds();
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFProjectDefinition, dmfDefinitionGroupExecution.DefinitionGroup);
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFEntityName, dMFDefinitionGroupExecution.Entity);
    this.addRuntimeProperty(METApplicationInsightsEventProperties::LegalEntity, dMFDefinitionGroupExecution.Company);
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFExecutionID, dMFDefinitionGroupExecution.ExecutionId);
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFStagingErrorCount, int2Str(dMFDefinitionGroupExecution.StagingErrorCount));
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFStagingStatus, enum2Str(dMFDefinitionGroupExecution.StagingStatus));
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFTargetErrorCount, int2Str(dMFDefinitionGroupExecution.TargetErrorCount));
    this.addRuntimeProperty(METApplicationInsightsEventProperties::DMFTargetStatus, enum2Str(dMFDefinitionGroupExecution.TargetStatus));
    this.addRuntimeProperty(METApplicationInsightsEventProperties::CallStack, METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
    this.addRuntimeProperty(METApplicationInsightsEventProperties::ExceptionMessage, this.error);
    //ExceptionMessage
}
